(function () {
  var G = [3, 8, 13], pts = [];
  G.forEach(function (y) { G.forEach(function (x) { pts.push([x, y]); }); });
  var seed = 7, rnd = function () { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
  var out = [], seen = new Set(), paths = [];
  while (out.length < 100) {
    var len = 3 + Math.floor(rnd() * 3), path = [Math.floor(rnd() * 9)];
    while (path.length < len) { var n = Math.floor(rnd() * 9); if (path.indexOf(n) < 0) path.push(n); }
    var k = path.join("");
    if (seen.has(k) || seen.has(path.slice().reverse().join(""))) continue;
    seen.add(k);
    var s = pts[path[0]], e = pts[path[path.length - 1]];
    var dot = function (x, y, r) { return "M" + (x - r) + " " + y + "a" + r + " " + r + " 0 1 0 " + (2 * r) + " 0a" + r + " " + r + " 0 1 0 " + (-2 * r) + " 0"; };
    var sq = function (x, y) { return "M" + (x - 1.4) + " " + (y - 1.4) + "h2.8v2.8h-2.8z"; };
    var v = out.length % 5, closed = len > 3 && v === 1;
    var d = "M" + path.map(function (i) { return pts[i].join(" "); }).join("L") + (closed ? "Z" : "");
    d += v === 2 ? dot(s[0], s[1], 1.9) : v === 3 ? sq(s[0], s[1]) : dot(s[0], s[1], 0.9);
    if (v === 4) d += dot(e[0], e[1], 0.9);
    if (v === 0 && rnd() > 0.5) { var m = pts[path[1]]; d += dot(m[0], m[1], 1.6); }
    out.push(d);
    paths.push({ i: out.length - 1, path: path, len: len, v: v, closed: closed, d: d });
  }
  return JSON.stringify(paths);
})()
